static z_t4397_t z_io_stat(z_t81_t path) {
    z_t4397_t result = {0};
    char* path_cstr = z_sv_to_cstr(path);
    struct stat sb;
    int rc = stat(path_cstr, &sb);
    int e = errno;
    free(path_cstr);
    if (rc != 0) {
        z_t4104_t* boxed = (z_t4104_t*)z_xmalloc(sizeof(z_t4104_t));
        *boxed = z_io_errno_to_IoError(e);
        result.tag = Z_RESULT_BOX_FILESTAT_IOERROR_TAG_ERR;
        result.data = boxed;
        return result;
    }
    z_t4389_t fs = {0};
    z_io_fill_filestat(&fs, &sb);
    z_t4389_t* boxed = (z_t4389_t*)z_xmalloc(sizeof(z_t4389_t));
    *boxed = fs;
    result.tag = Z_RESULT_BOX_FILESTAT_IOERROR_TAG_OK;
    result.data = boxed;
    return result;
}


